        case 'wind': this.noise(0, { dur: 1.0, freq: 600, q: 0.5, vol: 0.2, slide: 1.6 }); break;
        case 'earth': this.tone(0, { freq: 90, dur: 0.5, type: 'sine', vol: 0.3, slide: 0.7 }); this.noise(0, { dur: 0.5, freq: 200, q: 0.6, vol: 0.25, slide: 0.5 }); break;
