// Teste headless do jogo — verifica console, FPS e inicialização
const puppeteer = require('puppeteer-core');
const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = '/home/runner/work/PlayGround/PlayGround';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.svg': 'image/svg+xml' };

function serve(port = 8971) {
  const server = http.createServer((req, res) => {
    let p = decodeURIComponent(req.url.split('?')[0]);
    if (p === '/') p = '/index.html';
    const file = path.join(ROOT, p);
    if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
      res.writeHead(404); res.end('nf'); return;
    }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
    fs.createReadStream(file).pipe(res);
  });
  return new Promise(r => server.listen(port, r));
}

(async () => {
  await serve();
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium',
    headless: 'new',
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--window-size=1280,800'],
    defaultViewport: { width: 1280, height: 800 },
  });
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (msg) => {
    if (['error', 'warning'].includes(msg.type())) errors.push(`[${msg.type()}] ${msg.text()}`);
  });
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

  await page.goto('http://localhost:8971/', { waitUntil: 'networkidle0', timeout: 30000 });
  await new Promise(r => setTimeout(r, 4000));

  // estado inicial
  const state1 = await page.evaluate(() => ({
    ready: !!window.__AETHERIA_READY,
    menuVisible: !document.getElementById('menu-screen').classList.contains('hidden'),
    errorVisible: !document.getElementById('error-screen').classList.contains('hidden'),
    hasGame: !!window.__GAME,
  }));
  console.log('STATE-1', JSON.stringify(state1));

  // captura do menu
  await page.screenshot({ path: '/tmp/opencode/shot_menu.jpg', type: 'jpeg', quality: 60 });

  if (state1.hasGame) {
    // iniciar novo jogo
    await page.evaluate(() => window.__GAME.startGame(false));
    await new Promise(r => setTimeout(r, 5000));
    const state2 = await page.evaluate(() => ({
      hudVisible: !document.getElementById('hud').classList.contains('hidden'),
      fps: window.__GAME.fps,
      playerPos: window.__AETHERIA_READY ? [
        Math.round(window.__GAME && window.__GAME.constructor && 0),
      ] : null,
      canvasDrawn: (() => {
        const c = document.getElementById('game-canvas');
        return c && c.width > 0;
      })(),
    }));
    console.log('STATE-2', JSON.stringify(state2));
    await new Promise(r => setTimeout(r, 3000));
    const state3 = await page.evaluate(() => ({ fps: Math.round(window.__GAME.fps) }));
    console.log('FPS', JSON.stringify(state3));
    await page.screenshot({ path: '/tmp/opencode/shot_game.jpg', type: 'jpeg', quality: 60 });
  }

  console.log('--- CONSOLE ISSUES ---');
  errors.slice(0, 40).forEach(e => console.log(e));
  if (errors.length === 0) console.log('(nenhum erro de console)');
  await browser.close();
})().catch(e => { console.error('TEST FAIL', e); process.exit(1); });

