(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 120000 });
  const page = await browser.newPage();
  page.on('pageerror', e => console.log('[pageerror]', e.message));
  await page.goto('http://localhost:8976/', { waitUntil: 'domcontentloaded' });
  await new Promise(r => setTimeout(r, 5000));
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await new Promise(r => setTimeout(r, 4000));
  await page.evaluate(() => { document.querySelector('#modal-layer .modal')?.click(); });
  await new Promise(r => setTimeout(r, 500));
  const out = await page.evaluate(async () => {
    const THREE = (await import('./vendor/three.module.js'));
    const cam = window.__G.camera;
    const scene = window.__GAME.scene;
    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(new THREE.Vector2(0, 0.5), cam);
    const hits = raycaster.intersectObjects(scene.children, true);
    const h = hits[0];
    if (!h) return 'no hit';
    const o = h.object;
    o.geometry.computeBoundingBox();
    const bb = o.geometry.boundingBox;
    o.geometry.computeBoundingSphere();
    const bs = o.geometry.boundingSphere;
    const wp = new THREE.Vector3(); o.getWorldPosition(wp);
    const ws = new THREE.Vector3(); o.getWorldScale(ws);
    return {
      dist: h.distance,
      geoPos: [bb.min.x.toFixed(1), bb.min.y.toFixed(1), bb.min.z.toFixed(1), '|', bb.max.x.toFixed(1), bb.max.y.toFixed(1), bb.max.z.toFixed(1)],
