  }));
  console.log('apos clique 1', JSON.stringify(s1));
  await page.mouse.click(640, 400);
  await sleep(600);
  const s2 = await page.evaluate(() => ({
    paused: window.__G.paused,
    modalHTML: document.getElementById('modal-layer').innerHTML.slice(0, 120),
  }));
  console.log('apos clique 2', JSON.stringify(s2));

  // teclado: segura W e verifica input direto
  await page.keyboard.down('KeyW');
  await sleep(400);
  const s3 = await page.evaluate(() => ({
    keysSize: (window.__G && document) ? undefined : undefined,
    keysLen: require === undefined ? 0 : 0,
    move: null,
  }));
  const s4 = await page.evaluate(() => {
    // lê via import dinâmico
    return window.__inputProbe ? window.__inputProbe() : 'no-probe';
  });
  console.log('probe', JSON.stringify(s4));
