89:     const dmg = this.spellDamage(p.spell);
90:     if (enemy) {
91:       enemy.takeDamage(dmg, { x: p.vx * 0.06, z: p.vz * 0.06, kb: 3, element: p.element, source: 'magic', crit: Math.random() < 0.15 });
92:       if (p.spell.freeze) enemy.freeze(p.spell.freeze * (1 + G.attributes.poder * 0.05));
93:     } else {
94:       // impacto no chão: área pequena
95:       this._areaDamage(pos.x, pos.z, p.spell.radius * 0.7, dmg * 0.7, p.element, p.spell, 0);
96:     }
97:   }
