155:   _aimPoint(origin, camDir, maxRange = 30) {
156:     // ponto alvo: inimigo próximo à linha de mira, senão ponto a X metros
157:     const enemies = G.enemies ? G.enemies.active : [];
158:     let best = null, bestScore = 0.9;
159:     for (const e of enemies) {
160:       if (e.dead) continue;
161:       const to = new THREE.Vector3(e.root.position.x, e.root.position.y + 0.8, e.root.position.z).sub(origin);
162:       const dist = to.length();
163:       if (dist > maxRange + 6) continue;
164:       to.normalize();
165:       const dot = to.dot(camDir);
166:       if (dot > bestScore) { bestScore = dot; best = e; }
167:     }
168:     if (best) {
169:       return { point: new THREE.Vector3(best.root.position.x, best.root.position.y + 0.8, best.root.position.z), enemy: best };
170:     }
171:     return { point: origin.clone().addScaledVector(camDir, maxRange), enemy: null };
172:   }
