178:     const p = { mesh, spell, element: G.element, friendly, life: 3, grav: spell.id.includes('terra') ? 4 : 0 };
179:     const aim = this._aimPoint(origin, camDir);
180:     const dir = aim.point.sub(origin).normalize();
