464:   // dano em área (inimigos)
465:   _areaDamage(x, z, radius, dmg, element, spell, kb = 0, tick = false, stagger = false) {
466:     const enemies = G.enemies ? G.enemies.active : [];
467:     let hitAny = false;
468:     for (const e of enemies) {
469:       if (e.dead) continue;
470:       const d = Math.hypot(e.root.position.x - x, e.root.position.z - z);
471:       if (d > radius + e.radius) continue;
472:       if (tick && e.lastTick === G.playtime) continue;
473:       hitAny = true;
474:       const dx = (e.root.position.x - x) / (d || 1), dz = (e.root.position.z - z) / (d || 1);
475:       e.takeDamage(dmg, { x: dx, z: dz, kb, element, source: 'magic', crit: Math.random() < 0.12 });
476:       if (spell?.freeze) e.freeze(spell.freeze);
477:       if (stagger) e.stunned = Math.max(e.stunned, 1.2);
478:       if (tick) e.lastTick = G.playtime;
479:     }
480:     return hitAny;
481:   }
